import java.util.*;

class Solution {
    private static class Node {
        Node[] next = new Node[26];
        boolean isEnd;
    }

    private final Node root = new Node();

    public List<String> builtWords(String[] words) {
        String[] ws = words.clone();
        Arrays.sort(ws, (a, b) -> a.length() - b.length()); // shorter words first
        List<String> out = new ArrayList<>();
        for (String w : ws) {
            if (canBuild(w)) out.add(w);  // only shorter words are in the trie now
            insert(w);
        }
        return out;
    }

    private boolean canBuild(String w) {
        int n = w.length();
        boolean[] ok = new boolean[n + 1];
        ok[0] = true;
        for (int i = 0; i < n; i++) {
            if (!ok[i]) continue;
            Node cur = root;
            for (int j = i; j < n; j++) {
                cur = cur.next[w.charAt(j) - 'a'];
                if (cur == null) break;
                if (cur.isEnd) ok[j + 1] = true; // w[i..j] is a known shorter word
            }
            if (ok[n]) return true;
        }
        return ok[n];
    }

    private void insert(String w) {
        Node cur = root;
        for (char c : w.toCharArray()) {
            int k = c - 'a';
            if (cur.next[k] == null) cur.next[k] = new Node();
            cur = cur.next[k];
        }
        cur.isEnd = true;
    }
}

