class Solution:
    def builtWords(self, words: List[str]) -> List[str]:
        seen, out = set(), []
        for w in sorted(words, key=len):
            n = len(w); ok = [True] + [False] * n
            for i in range(1, n + 1):
                for j in range(i):
                    if ok[j] and w[j:i] in seen: ok[i] = True; break
            if seen and ok[n]: out.append(w)
            seen.add(w)
        return out

