function builtWords(words) {
  const all = new Set(words), out = [];
  for (const w of words) {
    const memo = new Map();
    const go = (i, cnt) => {
      if (i === w.length) return cnt >= 2;
      const key = i * 2 + (cnt >= 1 ? 1 : 0);
      if (memo.has(key)) return memo.get(key);
      let r = false;
      for (let j = i + 1; j <= w.length && !r; j++) if (all.has(w.slice(i, j))) r = go(j, Math.min(cnt + 1, 2));
      memo.set(key, r); return r;
    };
    if (go(0, 0)) out.push(w);
  }
  return out;
}
